 "content": "def transform(grid):
    """Arrange colored objects in a compact staircase, ordered by color's position."""
    h, w = len(grid), len(grid[0])
    seen = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                seen.setdefault(color, []).append((r, c))
    # objects ordered by decreasing x (left-to-right via their input columns),
    # preserving order of encountered objects; here colors are the distinct objects.
    objects = []
    for color, cells in seen.items():
        rs = [p[0] for p in cells]; cs = [p[1] for p in cells]
        objects.append((min(cs), min(rs), color, max(rs)-min(rs)+1, max(cs)-min(cs)+1))
    objects.sort(key=lambda o: o[0])
    # Each object moves to the next diagonal slot: retain shape and pack from top-left,
    # with successive objects shifted down/right by preceding shape extents.
    out = [[0]*w for _ in range(h)]
    r0 = c0 = 0
    for _, _, color, oh, ow in objects:
        for dr in range(oh):
            for dc in range(ow):
                # Replicate the object's bounding-box occupancy.
                out[r0+dr][c0+dc] = color
        r0 += oh - 1
        c0 += ow - 1
    return out

