 "content": "def transform(grid):
    """Pack each nonzero color object into a staircase, preserving its shape.

    Objects are ordered by their leftmost input column. Each next object is
    placed so its top-left aligns diagonally with the previous object's
    bottom-right extent (one-cell overlap in both axes).
    """
    h, w = len(grid), len(grid[0])
    positions = {}
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value:
                positions.setdefault(value, []).append((r, c))
    objects = []
    for color, cells in positions.items():
        top = min(r for r, c in cells)
        left = min(c for r, c in cells)
        height = max(r for r, c in cells) - top + 1
        width = max(c for r, c in cells) - left + 1
        shape = {(r - top, c - left) for r, c in cells}
        objects.append((left, color, height, width, shape))
    objects.sort(key=lambda obj: obj[0])

    output = [[0] * w for _ in range(h)]
    top = left = 0
    for i, (_, color, height, width, shape) in enumerate(objects):
        for dr, dc in shape:
            r, c = top + dr, left + dc
            if 0 <= r < h and 0 <= c < w:
                output[r][c] = color
        if i + 1 < len(objects):
            top += height - 1
            left += width - 1
    return output

